package org.apache.commons.math3.analysis.differentiation;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.apache.commons.math3.exception.DimensionMismatchException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.util.ArithmeticUtils;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathArrays;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for {@link DSCompiler#atan2(double[], int, double[], int, double[], int)}.
 * Designed to maximize branch and line coverage.
 */
public class DSCompiler_atan2_TriageGen1Test {

    private static final double EPSILON = 1e-12;

    @Test
    public void testAtan2PositiveX() {
        // Case where x[xOffset] >= 0
        int parameters = 1;
        int order = 2;
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        // Set values: y = 1.0, x = 1.0
        y[0] = 1.0;
        x[0] = 1.0;

        // Fill other indices to ensure no NaN propagation if they are used in loops
        for (int i = 1; i < size; i++) {
            y[i] = 0.0;
            x[i] = 0.0;
        }

        compiler.atan2(y, 0, x, 0, result, 0);

        // The implementation forces result[resultOffset] = FastMath.atan2(y[yOffset], x[xOffset])
        // which covers the special cases and the core logic.
        double expected = FastMath.atan2(1.0, 1.0);
        Assert.assertEquals("atan2 failed for positive x", expected, result[0], EPSILON);
    }

    @Test
    public void testAtan2NegativeX() {
        // Case where x[xOffset] < 0
        int parameters = 1;
        int order = 2;
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        // Set values: y = 1.0, x = -1.0
        y[0] = 1.0;
        x[0] = -1.0;

        for (int i = 1; i < size; i++) {
            y[i] = 0.0;
            x[i] = 0.0;
        }

        compiler.atan2(y, 0, x, 0, result, 0);

        double expected = FastMath.atan2(1.0, -1.0);
        Assert.assertEquals("atan2 failed for negative x", expected, result[0], EPSILON);
    }

    @Test
    public void testAtan2SpecialCases() {
        int parameters = 1;
        int order = 1;
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);

        double[] y = new double[1];
        double[] x = new double[1];
        double[] result = new double[1];

        // Test 0, 0
        y[0] = 0.0; x[0] = 0.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals(FastMath.atan2(0.0, 0.0), result[0], EPSILON);

        // Test Infinity
        y[0] = Double.POSITIVE_INFINITY; x[0] = 0.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals(FastMath.atan2(Double.POSITIVE_INFINITY, 0.0), result[0], EPSILON);

        // Test -0, 0
        y[0] = -0.0; x[0] = 0.0;
        compiler.atan2(y, 0, x, 0, result, 0);
        Assert.assertEquals(FastMath.atan2(-0.0, 0.0), result[0], EPSILON);
    }

    @Test
    public void testAtan2WithOffsets() {
        int parameters = 1;
        int order = 1;
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);

        double[] y = new double[3];
        double[] x = new double[3];
        double[] result = new double[3];

        // Use offsets to ensure logic respects them
        y[1] = 1.0;
        x[1] = 1.0;

        compiler.atan2(y, 1, x, 1, result, 1);

        double expected = FastMath.atan2(1.0, 1.0);
        Assert.assertEquals("atan2 failed with offsets", expected, result[1], EPSILON);
    }

    @Test
    public void testAtan2NegativeXBranchCoverage() {
        // To hit the (tmp2[0] <= 0) branch inside the else block
        // We need to ensure the logic flows through the negative x path.
        // Since the method ends with result[resultOffset] = FastMath.atan2(...),
        // the entire complex calculation is effectively overwritten for the first element.
        // However, the loop for i=1 to tmp2.length still executes.

        int parameters = 1;
        int order = 3; // higher order to ensure tmp2.length > 1
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        x[0] = -1.0;
        y[0] = 1.0; // tmp2[0] will be atan(y/(r-x)) which is positive, so we test the other side

        // To trigger (tmp2[0] <= 0) being true:
        // y/(r-x) <= 0. If x is negative, r-x is positive. So y must be <= 0.
        y[0] = -1.0; 

        compiler.atan2(y, 0, x, 0, result, 0);

        double expected = FastMath.atan2(-1.0, -1.0);
        Assert.assertEquals(expected, result[0], EPSILON);
    }
}
